	query := fmt.Sprintf(`SELECT "id", "client_id", "user_id", "grant_id", "redirect_uri", "code_challenge", "state", "scope", "resource", "nonce", "code_hash", "created_at", "expires_at", "used_at" FROM oauth_code WHERE id IN (%s)`, strings.Join(placeholders, ", "))

