	// Optional field: state - only add if set
	{
		if !reflect.ValueOf(input.State).IsZero() {
			fields = append(fields, `state`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.State)
		}
	}
	// Optional field: scope - only add if set
	{
		if !reflect.ValueOf(input.Scope).IsZero() {
			fields = append(fields, `scope`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.Scope)
		}
	}
	// Required field: resource
	fields = append(fields, `resource`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Resource)
	// Required field: nonce
	fields = append(fields, `nonce`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Nonce)
