// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is.
func (r *OAuthCodeRepository) UpsertOne(ctx context.Context, input *types.OAuthCode, on OAuthCodeUniqueKey, update *OAuthCodeUpdate) (*types.OAuthCode, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. One
// whose update sets no field updates nothing, so the row keeps its version
// and no trigger fires, and reads the row back. A write that
// may take more than one statement runs in a transaction of its own when
// none is open.
func (r *OAuthCodeRepository) UpsertOneResult(ctx context.Context, input *types.OAuthCode, on OAuthCodeUniqueKey, update *OAuthCodeUpdate, opts *UpsertOptions) (UpsertResult[*types.OAuthCode], error) {
	var none UpsertResult[*types.OAuthCode]
	key, ok := oAuthCodeUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: OAuthCode has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "OAuthCode", string(on))
	}
	if update == nil {
		update = &OAuthCodeUpdate{}
	}
	write := func(repo *OAuthCodeRepository) (UpsertResult[*types.OAuthCode], error) {
		result, err := repo.upsertRow(ctx, input, on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	}
	if !opts.OnlyIfChanged && oAuthCodeUpdateSetsField(update) {
		return write(r)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.OAuthCode], error) {
		return write(&OAuthCodeRepository{tx: tx, txDB: r.database()})
	})
}

// oAuthCodeUpdateSetsField reports whether update sets a field, a value or a
// null: UpdatedBy alone sets none, but stamps the row an update that sets
// one changes.
func oAuthCodeUpdateSetsField(update *OAuthCodeUpdate) bool {
	return update != nil && *update != (OAuthCodeUpdate{UpdatedBy: update.UpdatedBy})
}

