// UpsertMany inserts each input, or, when a row already holds its value of
// the unique key on, sets each field update names of that row to the value
// the input would have inserted, and returns each input's row and what it
// did with it, in the inputs' order (D89). One statement writes a batch of
// rows, opts.Batch or as many as Postgres binds the parameters of, and more
// rows take a statement per batch, in one transaction; a write that may
// take more than one statement runs in a transaction of its own when none
// is open. One whose update names no field updates nothing, so each row
// that holds a key keeps its version and no trigger fires, and reads those
// rows back. Two inputs of one batch that hold one key fail
// the statement, and a key over an expression, whose rows the statement's
// cannot be matched to the inputs by, is refused.
func (r *OAuthCodeRepository) UpsertMany(ctx context.Context, inputs []*types.OAuthCode, on OAuthCodeUniqueKey, update OAuthCodeFields, opts *UpsertOptions) ([]UpsertResult[*types.OAuthCode], error) {
	key, ok := oAuthCodeUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: OAuthCode has no unique key %q", string(on))
	}
	if key.rows == "" {
		return nil, upsertExpressionKey("UpsertMany", "OAuthCode", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if update.Id {
		return nil, fmt.Errorf("orm: UpsertMany of OAuthCode sets the fields an update sets, not id")
	}
	if update.CreatedAt {
		return nil, fmt.Errorf("orm: UpsertMany of OAuthCode sets the fields an update sets, not createdAt")
	}
	batch, err := upsertBatch("OAuthCode", opts.Batch, 5041)
	if err != nil {
		return nil, err
	}
	if len(inputs) == 0 {
		return []UpsertResult[*types.OAuthCode]{}, nil
	}
	if len(inputs) <= batch && !opts.OnlyIfChanged && update != (OAuthCodeFields{}) {
		return r.upsertBatches(ctx, inputs, on, update, batch, false)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]UpsertResult[*types.OAuthCode], error) {
		return (&OAuthCodeRepository{tx: tx, txDB: r.database()}).upsertBatches(ctx, inputs, on, update, batch, opts.OnlyIfChanged)
	})
}

